import{_ as t,o,c,a3 as a}from"./chunks/framework.cNy3aYYk.js";const h=JSON.parse('{"title":"Tenant API v1 — Contracts","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Contracts | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-contracts"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Contracts | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-contracts"}]]},"headers":[],"relativePath":"api/tenant-v1-contracts.md","filePath":"api/tenant-v1-contracts.md","lastUpdated":1790204574000}'),d={name:"api/tenant-v1-contracts.md"};function n(s,e,i,r,l,p){return o(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-api-v1-—-contracts" tabindex="-1">Tenant API v1 — Contracts <a class="header-anchor" href="#tenant-api-v1-—-contracts" aria-label="Permalink to &quot;Tenant API v1 — Contracts&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:contracts</code>, plus permission middleware / policies.</p><p>Assignee scoping: without <code>contracts.assign</code> (and not superadmin), list/stats/view/update/<strong>send</strong>/<strong>accept</strong>/<strong>convert</strong> only include contracts where <code>assigned_to</code> is the current user.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-contracts-stats" tabindex="-1">GET <code>/contracts/stats</code> <a class="header-anchor" href="#get-contracts-stats" aria-label="Permalink to &quot;GET `/contracts/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Counts include <code>sent</code> alongside <code>draft</code>, <code>active</code>, <code>expired</code>, and <code>terminated</code>.</p><h2 id="contracts-crud" tabindex="-1">Contracts CRUD <a class="header-anchor" href="#contracts-crud" aria-label="Permalink to &quot;Contracts CRUD&quot;">​</a></h2><h3 id="get-contracts" tabindex="-1">GET <code>/contracts</code> <a class="header-anchor" href="#get-contracts" aria-label="Permalink to &quot;GET `/contracts`&quot;">​</a></h3><p>Query: <code>search</code>, <code>status</code>, <code>opportunity_id</code>, <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_contracts</code>, <code>trashed</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>status</code>, <code>opportunity</code>, <code>quotation</code> (when linked), <code>invoice_count</code>, assignee/creator refs, <code>latest_note</code>, plus acceptance fields when present: <code>has_acceptance_link</code>, <code>acceptance_link_expires_at</code>, <code>accepted_at</code>, <code>accepted_by_name</code>, <code>accepted_by_email</code>, <code>accepted_by_phone</code>, <code>acceptance_ip</code>, <code>acceptance_signature_method</code>, <code>has_acceptance_signature</code>, <code>has_acceptance_id_document</code>, <code>acceptance_id_document_type</code>, <code>acceptance_id_document_original_name</code> (file paths are never exposed).</p><h3 id="post-contracts" tabindex="-1">POST <code>/contracts</code> <a class="header-anchor" href="#post-contracts" aria-label="Permalink to &quot;POST `/contracts`&quot;">​</a></h3><p>Body: <code>opportunity_id</code> (required), <code>quotation_id</code> (optional — only valid when the <strong>Quotations</strong> module is entitled, the quotation is not soft-deleted, the actor may access the quotation, and the quotation belongs to the same opportunity; see <code>LinkableQuotation</code>), <code>title</code> (required), <code>party_name</code>, <code>start_date</code> (required), <code>end_date</code>, <code>value</code>, <code>currency</code> (3-letter, default <code>USD</code>), <code>description</code> (HTML memo, sanitized server-side, max 50000), <code>notes</code> (HTML memo, sanitized server-side, max 50000), <code>assigned_to</code>.</p><h3 id="get-contracts-id" tabindex="-1">GET <code>/contracts/{id}</code> <a class="header-anchor" href="#get-contracts-id" aria-label="Permalink to &quot;GET `/contracts/{id}`&quot;">​</a></h3><p>Includes opportunity, quotation (when linked), related <code>invoices</code> (<code>id</code>/<code>number</code>/<code>status</code>), <code>quotation_already_invoiced</code> (true when the linked quotation already has any invoice), assignee, creator, <code>description</code> / <code>notes</code> HTML memos, comments (<code>contract_notes</code>), timeline activities, and acceptance metadata (same fields as list, including evidence flags). Embedded <code>contract_notes</code> and timeline/domain <code>activities</code> are <strong>newest-first</strong> (<code>created_at</code> DESC, then <code>id</code> DESC).</p><h3 id="get-contracts-id-acceptance-signature" tabindex="-1">GET <code>/contracts/{id}/acceptance-signature</code> <a class="header-anchor" href="#get-contracts-id-acceptance-signature" aria-label="Permalink to &quot;GET `/contracts/{id}/acceptance-signature`&quot;">​</a></h3><p>Permission: <code>contracts.view</code> (assignee-scoped). Streams the stored signature image when <code>has_acceptance_signature</code> is true; otherwise 404. Records <code>acceptance_evidence_downloaded</code> on the timeline.</p><h3 id="get-contracts-id-acceptance-id-document" tabindex="-1">GET <code>/contracts/{id}/acceptance-id-document</code> <a class="header-anchor" href="#get-contracts-id-acceptance-id-document" aria-label="Permalink to &quot;GET `/contracts/{id}/acceptance-id-document`&quot;">​</a></h3><p>Permission: <code>contracts.view</code> (assignee-scoped). Streams the uploaded ID/passport file when <code>has_acceptance_id_document</code> is true; otherwise 404. Records <code>acceptance_evidence_downloaded</code> on the timeline.</p><h3 id="get-contracts-id-pdf" tabindex="-1">GET <code>/contracts/{id}/pdf</code> <a class="header-anchor" href="#get-contracts-id-pdf" aria-label="Permalink to &quot;GET `/contracts/{id}/pdf`&quot;">​</a></h3><p>Permission: <code>contracts.view</code> (assignee-scoped). Extra limiter <code>throttle:contracts-pdf</code>. Returns <code>application/pdf</code> attachment. Branded layout matches other sales documents (logo, button color, company profile). Includes party, dates, value, sanitized description/notes HTML, and — when accepted — signer metadata plus the signature image (ID files are not embedded).</p><h3 id="put-contracts-id" tabindex="-1">PUT <code>/contracts/{id}</code> <a class="header-anchor" href="#put-contracts-id" aria-label="Permalink to &quot;PUT `/contracts/{id}`&quot;">​</a></h3><p>Partial update of <strong>draft</strong> contracts only. Non-draft contracts return 422 on <code>status</code> (<code>Only draft contracts can be edited.</code>). Assignment after send/activate uses <code>POST /contracts/{id}/assign</code>. Status changes use <code>POST /contracts/{id}/status</code> (or dedicated send/accept actions).</p><h3 id="delete-contracts-id" tabindex="-1">DELETE <code>/contracts/{id}</code> <a class="header-anchor" href="#delete-contracts-id" aria-label="Permalink to &quot;DELETE `/contracts/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>contracts.delete</code>. Keeps acceptance evidence files so restore can recover them.</p><h3 id="post-contracts-id-restore" tabindex="-1">POST <code>/contracts/{id}/restore</code> <a class="header-anchor" href="#post-contracts-id-restore" aria-label="Permalink to &quot;POST `/contracts/{id}/restore`&quot;">​</a></h3><p>Permission: <code>contracts.restore</code>.</p><h3 id="delete-contracts-id-force" tabindex="-1">DELETE <code>/contracts/{id}/force</code> <a class="header-anchor" href="#delete-contracts-id-force" aria-label="Permalink to &quot;DELETE `/contracts/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted contract. Permission: <code>contracts.force.delete</code>. Purges signature and ID evidence objects from storage.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-contracts-id-assign" tabindex="-1">POST <code>/contracts/{id}/assign</code> <a class="header-anchor" href="#post-contracts-id-assign" aria-label="Permalink to &quot;POST `/contracts/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><p>Permission: <code>contracts.assign</code>.</p><h3 id="post-contracts-id-send" tabindex="-1">POST <code>/contracts/{id}/send</code> <a class="header-anchor" href="#post-contracts-id-send" aria-label="Permalink to &quot;POST `/contracts/{id}/send`&quot;">​</a></h3><p>Transitions <code>draft → sent</code>. Permission: <code>contracts.send</code> (assignee-scoped unless the actor has <code>contracts.assign</code> or is superadmin). <strong>Status-only</strong> — does not email or generate a PDF. Issues a hashed customer acceptance token (plaintext returned only from <code>POST …/acceptance-link</code> or embedded in email). Records <code>signature_requested</code>.</p><h3 id="post-contracts-id-email" tabindex="-1">POST <code>/contracts/{id}/email</code> <a class="header-anchor" href="#post-contracts-id-email" aria-label="Permalink to &quot;POST `/contracts/{id}/email`&quot;">​</a></h3><p><code>{ &quot;to&quot;?: string[], &quot;cc&quot;?: string[], &quot;bcc&quot;?: string[], &quot;subject&quot;: string, &quot;message&quot;: string, &quot;attach_pdf&quot;?: boolean }</code></p><p>Permission: <code>contracts.send</code> (assignee-scoped unless the actor has <code>contracts.assign</code> or is superadmin). Throttle: <code>billing-document-email</code> (10/min per user).</p><p>Requires the contract to already be sent — draft returns 422 on <code>status</code>. Allowed for <code>sent</code>, <code>active</code>, <code>expired</code>, and <code>terminated</code>.</p><p>When <code>to</code> is omitted, resolves the recipient from the linked opportunity’s contact email, then company email. If no address is found, returns 422 on <code>to</code>.</p><p>Queues a branded email via the tenant mailer (optional PDF attachment from <code>ContractPdfService</code>). For <strong>Sent</strong> contracts, rotates the acceptance token and appends the accept URL to the message body. Records an <code>emailed</code> timeline entry and a tenant email log row (<code>notification_type</code>: <code>contract.emailed</code>).</p><h3 id="post-contracts-id-acceptance-link" tabindex="-1">POST <code>/contracts/{id}/acceptance-link</code> <a class="header-anchor" href="#post-contracts-id-acceptance-link" aria-label="Permalink to &quot;POST `/contracts/{id}/acceptance-link`&quot;">​</a></h3><p>Permission: <code>contracts.send</code> (assignee-scoped). Requires status <code>sent</code>. Rotates the acceptance token and returns <code>{ url, expires_at, has_acceptance_link, acceptance_link_expires_at }</code>.</p><h3 id="post-contracts-id-accept" tabindex="-1">POST <code>/contracts/{id}/accept</code> <a class="header-anchor" href="#post-contracts-id-accept" aria-label="Permalink to &quot;POST `/contracts/{id}/accept`&quot;">​</a></h3><p>Transitions <code>sent → active</code>. Permission: <code>contracts.accept</code> (assignee-scoped unless the actor has <code>contracts.assign</code> or is superadmin). Clears any outstanding acceptance token.</p><h3 id="public-customer-accept-unauthenticated" tabindex="-1">Public customer accept (unauthenticated) <a class="header-anchor" href="#public-customer-accept-unauthenticated" aria-label="Permalink to &quot;Public customer accept (unauthenticated)&quot;">​</a></h3><p>Requires tenancy (domain / <code>X-Tenant-Domain</code>) and Contracts entitlement. Throttle: <code>contract-acceptance</code> (20/min per IP).</p><ul><li><code>GET /public/contracts/accept/{token}</code> — summary (title, party, dates, value, workspace name, description, expiry, <code>acceptance_requirements: { phone, signature_image, id_document }</code>). Invalid/expired/used → 404.</li><li><code>POST /public/contracts/accept/{token}</code> — multipart or JSON. Always: <code>accepted_by_name</code>, <code>accepted_by_email</code>. When requirements demand: <code>accepted_by_phone</code>; <code>signature</code> file + <code>signature_method</code> (<code>drawn</code>|<code>uploaded</code>); <code>id_document</code> file + <code>id_document_type</code> (<code>national_id</code>|<code>passport</code>|<code>other</code>). Marks <strong>active</strong>, stores signer + IP (+ user agent / evidence files), invalidates token, records <code>signed</code> activity. Uploads honor workspace Storage quota and upload policy. Enabling signature/ID Settings requires Storage entitlement.</li></ul><h3 id="post-contracts-id-status" tabindex="-1">POST <code>/contracts/{id}/status</code> <a class="header-anchor" href="#post-contracts-id-status" aria-label="Permalink to &quot;POST `/contracts/{id}/status`&quot;">​</a></h3><p><code>{ &quot;status&quot;: &quot;draft&quot;|&quot;sent&quot;|&quot;active&quot;|&quot;expired&quot;|&quot;terminated&quot; }</code></p><p>Permission: <code>contracts.update</code>. Rejects disallowed transitions (including re-entering the same status) with a 422 validation error on <code>status</code>. Records a <code>status_changed</code> timeline entry. Prefer dedicated <code>POST …/send</code> and <code>POST …/accept</code> for send/activate-from-sent (correct permission gates). Draft → <code>active</code> supports <strong>Activate without signature</strong>. Expire/terminate clear outstanding acceptance links.</p><p>Allowed transitions:</p><ul><li><code>draft</code> → <code>sent</code> | <code>active</code> | <code>terminated</code></li><li><code>sent</code> → <code>active</code> | <code>expired</code> | <code>terminated</code></li><li><code>active</code> → <code>expired</code> | <code>terminated</code></li></ul><h3 id="post-contracts-id-convert" tabindex="-1">POST <code>/contracts/{id}/convert</code> <a class="header-anchor" href="#post-contracts-id-convert" aria-label="Permalink to &quot;POST `/contracts/{id}/convert`&quot;">​</a></h3><p>Creates a <strong>draft</strong> <code>CustomerInvoice</code> from an <strong>active</strong> contract (repeatable — progress billing):</p><ul><li>Requires the <strong>Invoices</strong> module to be entitled (soft, call-time check — no <code>module_dependencies</code> row). Returns 422 if Invoices is not installed.</li><li>Copies linked quotation lines when present; otherwise a single line from <code>value</code>. Rejects if there is no value and no quotation lines.</li><li>Sets <code>customer_invoices.contract_id</code> and copies <code>quotation_id</code> when the contract is linked to a quotation</li><li>Does <strong>not</strong> hard-block when the quotation is already invoiced — the confirm UI warns; the API allows another invoice</li><li><strong>Second and later</strong> invoices for the same contract require <code>{ &quot;acknowledge_repeat_billing&quot;: true }</code> (422 on <code>acknowledge_repeat_billing</code> otherwise). The SPA confirm dialog always sends this flag.</li><li>Records a <code>converted</code> activity (<code>Created invoice {number}</code>)</li></ul><p>Permission: <code>contracts.convert</code> (assignee-scoped unless the actor has <code>contracts.assign</code> or is superadmin). Rejects with a 422 if the contract is not active. Returns the created <strong>invoice</strong> (<code>CustomerInvoiceResource</code>) with HTTP 201.</p><h3 id="post-contracts-id-notes" tabindex="-1">POST <code>/contracts/{id}/notes</code> <a class="header-anchor" href="#post-contracts-id-notes" aria-label="Permalink to &quot;POST `/contracts/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><p>Permission: <code>contracts.update</code>.</p><h3 id="get-contracts-id-timeline" tabindex="-1">GET <code>/contracts/{id}/timeline</code> <a class="header-anchor" href="#get-contracts-id-timeline" aria-label="Permalink to &quot;GET `/contracts/{id}/timeline`&quot;">​</a></h3><p>Domain timeline entries (<code>created</code>, <code>updated</code>, <code>assigned</code>, <code>status_changed</code>, <code>converted</code>, <code>note_added</code>, <code>deleted</code>, <code>restored</code>, <code>emailed</code>, <code>signature_requested</code>, <code>signed</code>).</p>',62)])])}const m=t(d,[["render",n]]);export{h as __pageData,m as default};
